import{_ as t,c as o,o as a,ah as n,ao as s,ap as p}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"무지개 다리 건너편 — 모든 생물과 세우신 하나님의 언약","description":"무지개 다리는 아름다운 표현이지만, 성경의 무지개는 더 큽니다. 하나님께서 모든 생물과 세우신 영원한 언약입니다.","frontmatter":{"title":"무지개 다리 건너편 — 모든 생물과 세우신 하나님의 언약","description":"무지개 다리는 아름다운 표현이지만, 성경의 무지개는 더 큽니다. 하나님께서 모든 생물과 세우신 영원한 언약입니다."},"headers":[],"relativePath":"ko/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"ko/pets-in-heaven/rainbow-bridge-covenant.md"}'),i={name:"ko/pets-in-heaven/rainbow-bridge-covenant.md"};function r(l,e,h,c,d,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>「다들 그 아이가 무지개 다리를 건넜다고 하더라고요. 그런데 그게 그냥 좋은 말인가요, 아니면 진짜 소망인가요?」</p><p class="pl-quote-soft">놀랍게도 성경에는 정말 무지개가 있습니다. 그리고 그 언약은 동물을 위해 세워졌습니다.</p></div><section class="pl-section"><h2>1. 그 무지개는 동물과 맺은 언약이었습니다</h2><p>홍수 이후 하나님은 노아와 언약을 세우시며 다시는 물로 땅을 멸하지 않겠다고 하셨습니다. 그런데 그 언약의 당사자는 노아와 그의 자손만이 아니었습니다.</p><blockquote><p><strong>창세기 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>「<em>모든 생물</em>」이라는 표현을 보세요. 새와 가축과 땅의 모든 짐승이 언약의 당사자로 이름이 올라 있습니다. 하나님은 무지개를 구름 속에 두어 <strong>당신과 땅, 그리고 모든 생물 사이의 언약의 표</strong>로 삼으셨습니다.</p><p>성경 전체에서 가장 주목받지 못하면서도 가장 다정한 사실 중 하나입니다. <strong>하나님은 한때 동물과 공식적으로, 영원히 언약을 세우셨습니다.</strong></p><p>그러니 사람들이 붙인 「무지개 다리」라는 이름이 그렇게 동떨어진 것도 아닙니다. 성경은 그 빛이 표적이라고 말합니다. 표적은 결코 「끝」을 뜻하지 않습니다. 「아직 더 있다」를 뜻합니다.</p></section><section class="pl-section"><h2>2. 오는 세상에서 그들은 평안히 눕습니다</h2><p>이사야가 하나님이 만드실 세상을 묘사할 때, 그 장면의 중심에는 동물이 있습니다.</p><blockquote><p><strong>이사야 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>그리고 요한계시록은 마지막 예배에서 누가 노래하는지 들려줍니다.</p><blockquote><p><strong>요한계시록 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>「모든 생물」이 예배합니다. 사람만이 아닙니다.</p><p>시편은 이 모든 것을 한 줄로 요약합니다.</p><blockquote><p><strong>시편 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>호흡이 있는 모든 것 — 그 아이까지 — 이 노래 안에 있습니다.</p></section><section class="pl-section"><h2>3. 그래서 무지개 다리 건너편에는 약속이 있습니다</h2><p>우리가 하나님을 대신해 약속을 더할 수는 없습니다. 하지만 그분이 이미 하신 말씀 안에 머물 수는 있습니다. 모든 생물과 언약을 세우셨고, 만드실 세상에는 동물이 평화롭게 살고, 마지막 예배에는 「모든 생물」이 있으며, 호흡 있는 모든 것이 그분을 찬양할 것입니다.</p><p>이 구절들은 「당신의 아이가 반드시 거기 있다」고 말하지 않습니다. 하지만 이런 기도를 온전히 정당하게 만듭니다. 「주님, 그 아이가 주님의 약속 안에 있기를 바랍니다.」 그리고 이분은 동물을 위해 무지개까지 남기신 하나님입니다.</p><p class="pl-quote-soft">생각해 보세요. 하나님이 동물을 위해 무지개를 남기셨다면, 당신의 아이를 기억하지 않으실까요?</p></section><div class="pl-quote"><p>「주님은 구름 속에 주님의 활을 두어 모든 생물과의 표적으로 삼으셨습니다.<br>그 빛을 보는 날, 저는 그 아이를 떠올리겠습니다.<br>약속하신 대로, 그 아이가 주님의 약속 안에서 평안하기를 바랍니다.<br>그리고 그리운 날들에 주님의 언약이 저를 붙들어 주시기를 바랍니다. 아멘.」</p></div><section class="pl-section"><h2>당신을 위한 작은 의식</h2><p>비 온 뒤 무지개가 뜬다면 그것을 여러분의 표적으로 삼으세요. 잠시 거기 서서 그 아이에게 말을 걸어 보세요. 결론이 필요하지도, 말이 완성될 필요도 없습니다. 성경에서 그 빛은 늘 「언약의 표적」이었고, 표적은 하나님이 잊지 않으셨다는 뜻입니다.</p><p><a href="/ko/pets-in-heaven/">← Pets in Heaven으로 돌아가기</a> ｜ 다음 글: <a href="/ko/pets-in-heaven/permission-to-grieve">슬퍼해도 괜찮습니다</a></p></section><div class="pl-cta"><h2>함께 본 풍경을 남겨 두세요.</h2><p>그 아이의 사진으로 추모 카드, 포스터, 짧은 영상을 만들어 보세요. 함께 걸었던 날들이 오래 남는 모습을 갖게 됩니다.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store에서 다운로드</a></div><div class="pl-bible"><h3>말씀이 계속 곁에 있도록</h3><p>이 글의 모든 구절은 성경에서 왔습니다. 무지개 성경 위젯 앱으로 언제든 말씀을 읽고 매일 말씀 위젯을 설정해 보세요. 그리운 날들에 작은 등불이 되어 줄 것입니다.</p><div class="pl-bible-shots"><figure><img src="'+s+'" alt="Rainbow Bible 홈 화면 위젯 — 2 Timothy 2:13" loading="lazy"><figcaption>매일 말씀을 홈 화면에</figcaption></figure><figure><img src="'+p+'" alt="Rainbow Bible — 하늘나라의 반려동물 주제, 마태복음 10:29-31" loading="lazy"><figcaption>「하늘나라의 반려동물」 주제로 전환해 읽기</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Store에서 무지개 성경 위젯 받기</a></div>',8)])])}const f=t(i,[["render",r]]);export{g as __pageData,f as default};
